async function load(id) {
  try {
    const res = await fetch('http://localhost:3000/u/' + id);
    if (!res.ok) throw new Error('HTTP ' + res.status);
    return await res.json();
  } catch (e) { return e.message; }
}
load(7).then(console.log);

const wait = ms => new Promise(r => setTimeout(r, ms));
async function timeIt(label, job) {
  const t = Date.now();
  await job();
  console.log(label, Math.round((Date.now() - t) / 100) * 100);
}
await timeIt('serial', async () => { await wait(100); await wait(100); });
await timeIt('together', () => Promise.all([wait(100), wait(100)]));
